#!/usr/bin/env bash
# Rebuilds the fork's two Pigeon outputs from their sources and compares them byte for byte with the
# files kept in package/. Reads the fork, writes only inside the work dir, repairs nothing.
#
# usage: bash third_party/camera_android_camerax_status_filter/pigeon_repro/reproduce.sh <empty work dir outside the repository>
# optional: ARCHIVE=<upstream.tar.gz> (its hash is checked; otherwise downloaded), PUB_CACHE=<dir>
# (otherwise a new one inside the work dir, which needs network).
# Exit 0 and last line REPRODUCED, or exit 1 and one FAIL line per difference.
set -eu
HERE=$(cd "$(dirname "$0")" && pwd)
FORK=$(cd "$HERE/.." && pwd)
WORK=${1:?work dir}

# What was approved. Changing any of these is a decision to review, not a maintenance edit.
PIGEON_VERSION=27.3.2
URL='https://pub.dev/api/archives/camera_android_camerax-0.7.4%2B8.tar.gz'
ARCHIVE_SHA=977f54512d338b3b36d7f82929794886766d8f41ae84a48fe103eb0106ecfe25
UPSTREAM_KOTLIN_SHA=e7713322b286d3f0d0bf3e33efc366b91addca7e8db2171186b47ef36a1c8b63
BASELINE_RAW_KOTLIN_SHA=8ad279e699cd9c16bc8cbb561c0c2cd915af5c8d1eb2df32f8da9ad02883ffe0

DEFINITION=pigeons/camerax_library.dart
COPYRIGHT=pigeons/copyright.txt
GEN_DART=lib/src/camerax_library.g.dart
GEN_KOTLIN=android/src/main/java/io/flutter/plugins/camerax/CameraXLibrary.g.kt

FAILED=0
fail() { echo "FAIL: $*"; FAILED=$((FAILED + 1)); }
stop() { echo "FAIL: $*"; echo "NOT REPRODUCED"; exit 1; }
sha_of() { sha256sum "$1" | cut -d' ' -f1; }
native_path() { if command -v cygpath > /dev/null; then cygpath -m "$1"; else echo "$1"; fi; }

# --- the work dir: nothing it holds can be taken for a result, and it is not a place Pigeon's relative
# output paths could reach the fork from.
mkdir -p "$WORK"
WORK=$(cd "$WORK" && pwd)
[ -z "$(ls -A "$WORK")" ] || stop "$WORK is not empty"
case "$WORK/" in "$FORK/"*) stop "the work dir is inside the fork";; esac
if git -C "$WORK" rev-parse --git-dir > /dev/null 2>&1; then stop "the work dir is inside a repository"; fi

# --- the generator: refused before anything runs
[ "$(tr -d '\r' < "$HERE/tool/pubspec.yaml" | sed -n 's/^  pigeon: //p')" = "$PIGEON_VERSION" ] \
  || stop "pigeon_repro/tool/pubspec.yaml does not pin pigeon $PIGEON_VERSION"
LOCKED=$(tr -d '\r' < "$HERE/tool/pubspec.lock" | awk '/^  pigeon:$/ {on = 1} on && /^    version:/ {gsub(/"/, "", $2); print $2; exit}')
[ "$LOCKED" = "$PIGEON_VERSION" ] || stop "pigeon_repro/tool/pubspec.lock locks pigeon $LOCKED, not $PIGEON_VERSION"

BEFORE=$(cat "$FORK/package/$GEN_DART" "$FORK/package/$GEN_KOTLIN" "$FORK/package/$DEFINITION" | sha256sum)

mkdir "$WORK/tool"
cp "$HERE/tool/pubspec.yaml" "$HERE/tool/pubspec.lock" "$WORK/tool/"
export PUB_CACHE=${PUB_CACHE:-$WORK/pub-cache}
# --enforce-lockfile also fails if a package's content hash differs from the lock.
(cd "$WORK/tool" && dart pub get --enforce-lockfile > "$WORK/pub-get.log" 2>&1) \
  || { cat "$WORK/pub-get.log"; stop "the locked generator could not be resolved"; }

# --- upstream's sources
if [ -n "${ARCHIVE:-}" ]; then cp "$ARCHIVE" "$WORK/upstream.tar.gz"; else curl -fsSL -o "$WORK/upstream.tar.gz" "$URL"; fi
[ "$(sha_of "$WORK/upstream.tar.gz")" = "$ARCHIVE_SHA" ] || stop "the upstream archive is not sha256 $ARCHIVE_SHA"
mkdir "$WORK/upstream"
tar -xzf "$WORK/upstream.tar.gz" -C "$WORK/upstream" --no-same-owner
[ "$(sha_of "$WORK/upstream/$GEN_KOTLIN")" = "$UPSTREAM_KOTLIN_SHA" ] || stop "upstream's Kotlin is not the known file"

# @ConfigurePigeon's output paths are relative: --base_path keeps them in the isolated folder, and
# --dart_out/--kotlin_out would not (the definition overrides them).
generate() { # definition base
  mkdir -p "$2/pigeons" "$2/lib/src" "$(dirname "$2/$GEN_KOTLIN")"
  cp "$FORK/package/$COPYRIGHT" "$2/pigeons/copyright.txt"
  (cd "$WORK/tool" && dart run pigeon --input "$(native_path "$1")" --base_path "$(native_path "$2")" \
    --package_name camera_android_camerax > "$2.log" 2>&1) || { cat "$2.log"; stop "pigeon failed on $1"; }
  [ -s "$2/$GEN_DART" ] && [ -s "$2/$GEN_KOTLIN" ] || stop "pigeon did not write both outputs for $1"
  # The bytes after it are the formatted ones, so the output of this run says which generator ran.
  grep -qF "// Autogenerated from Pigeon (v$PIGEON_VERSION), do not edit directly." "$2/$GEN_KOTLIN" \
    || stop "the generator that ran is not pigeon $PIGEON_VERSION"
  dart format --page-width 100 --output write "$(native_path "$2/$GEN_DART")" > /dev/null
}
generate "$WORK/upstream/$DEFINITION" "$WORK/baseline"
cp "$FORK/package/$DEFINITION" "$WORK/fork_definition.dart"
generate "$WORK/fork_definition.dart" "$WORK/fork"

same() { # expected actual what
  if cmp -s "$1" "$2"; then echo "ok: $3"; else fail "$3"; cmp "$1" "$2" || true; fi
}

# --- the method, tried on upstream: the generator's output of the unchanged definition
[ "$(sha_of "$WORK/baseline/$GEN_KOTLIN")" = "$BASELINE_RAW_KOTLIN_SHA" ] \
  || fail "the generator's Kotlin for upstream's definition is not the known output"
same "$WORK/upstream/$GEN_DART" "$WORK/baseline/$GEN_DART" "upstream's Dart = generator + dart format"

# --- Dart: the generator and dart format, nothing else
same "$FORK/package/$GEN_DART" "$WORK/fork/$GEN_DART" "package's Dart = generator + dart format"

# --- Kotlin: the same recorded change must produce the generator's new output...
NORMALIZE=$(native_path "$HERE/normalize_kotlin.dart")
mkdir "$WORK/result"
if (cd "$WORK" && dart "$NORMALIZE" raw "$(native_path "$WORK/baseline/$GEN_KOTLIN")" "$(native_path "$WORK/result/raw.kt")"); then
  same "$WORK/fork/$GEN_KOTLIN" "$WORK/result/raw.kt" "the recorded change is all the generator changed"
else
  fail "the recorded change does not apply to the generator's baseline"
fi
# ...and, in upstream's layout, the file kept in package/.
if (cd "$WORK" && dart "$NORMALIZE" formatted "$(native_path "$WORK/upstream/$GEN_KOTLIN")" "$(native_path "$WORK/result/formatted.kt")"); then
  same "$FORK/package/$GEN_KOTLIN" "$WORK/result/formatted.kt" "package's Kotlin = upstream + the recorded change"
else
  fail "the recorded change does not apply to upstream's Kotlin"
fi

[ "$BEFORE" = "$(cat "$FORK/package/$GEN_DART" "$FORK/package/$GEN_KOTLIN" "$FORK/package/$DEFINITION" | sha256sum)" ] \
  || fail "the fork changed during the run"

echo "dart sdk: $(dart --version 2>&1)"
echo "sha256 generator Kotlin, baseline: $(sha_of "$WORK/baseline/$GEN_KOTLIN")"
echo "sha256 generator Kotlin, fork:     $(sha_of "$WORK/fork/$GEN_KOTLIN")"
echo "sha256 generated Dart, fork:       $(sha_of "$WORK/fork/$GEN_DART")"
[ ! -f "$WORK/result/formatted.kt" ] || echo "sha256 reconstructed Kotlin:       $(sha_of "$WORK/result/formatted.kt")"
echo "sha256 package Kotlin:             $(sha_of "$FORK/package/$GEN_KOTLIN")"

if [ "$FAILED" -ne 0 ]; then echo "NOT REPRODUCED: $FAILED difference(s)"; exit 1; fi
echo REPRODUCED
